<script setup>
import WbProductImages from "../../components/WbProductImages.vue";
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {ElMessage} from 'element-plus';import {apiClient,currentApiCacheScope} from '../../utils/api.js';
const shops=ref([]),shop=ref(null),warehouse=ref(null),warehouses=ref([]),bound=ref(null),rows=ref([]),selection=ref([]),search=ref(''),quantity=ref(0),busy=ref(false),checked=ref(0),results=ref([]);let sequence=0;
const filtered=computed(()=>rows.value.filter(row=>[row.title,row.vendor_code,row.barcode].some(value=>String(value||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
async function load(){const id=++sequence,scope=currentApiCacheScope();rows.value=[];selection.value=[];results.value=[];warehouses.value=[];warehouse.value=null;if(!shop.value)return;busy.value=true;try{const [products,storage]=await Promise.all([apiClient.get(`/api/wb/products?shop_id=${shop.value}`,{noCache:true}),apiClient.get(`/api/wb/warehouses?shop_id=${shop.value}`,{noCache:true})]);if(id!==sequence||scope!==currentApiCacheScope())return;warehouses.value=storage.rows;bound.value=storage.selected;warehouse.value=storage.selected;rows.value=products.rows.flatMap(p=>(p.card.sizes||[]).map(size=>({key:p.nm_id+':'+size.chrtID,nm_id:p.nm_id,chrt_id:size.chrtID,title:p.title,vendor_code:p.vendor_code,card:p.card,sku:size.skus?.[0],barcode:(size.skus||[]).join(' / '),size:size.techSize||'通用',quantity:0,product_id:p.mappings.find(m=>m.ozon_sku===`WB-${size.chrtID}`)?.product_id})));}catch(e){if(id===sequence)ElMessage.error(e.message);}finally{if(id===sequence)busy.value=false;}}
async function bootstrap(){const scope=currentApiCacheScope();try{const r=await apiClient.get('/api/wb/shops',{noCache:true});if(scope!==currentApiCacheScope())return;shops.value=r.filter(s=>s.status==='active');shop.value=shops.value[0]?.id||null;await load();}catch(e){ElMessage.error(e.message);}}
function apply(){for(const row of selection.value)row.quantity=quantity.value;results.value=[];}
async function preview(){if(!selection.value.length)return;if(selection.value.length>20)return ElMessage.warning('请每批选择不超过 20 个规格核对库存。');if(Number(warehouse.value)!==Number(bound.value))return ElMessage.warning('请选择店铺当前绑定的仓库；更换绑定请到企业店铺设置。');busy.value=true;results.value=[];checked.value=0;const scope=currentApiCacheScope(),id=sequence,chosen=selection.value.map(row=>({...row}));try{const output=[];for(const row of chosen){try{const r=await apiClient.get(`/api/wb/stocks?shop_id=${shop.value}&nm_id=${row.nm_id}&chrt_id=${row.chrt_id}`,{noCache:true});if(scope!==currentApiCacheScope()||id!==sequence)return;output.push({...row,available:r.available,current:r.stocks?.find(s=>s.sku===row.sku)?.amount??null,error:r.available===null?(r.availability_message||'本地可分配量未核对，不能分配库存。'):!Number.isSafeInteger(row.quantity)||row.quantity<0||row.quantity>r.available?'目标数量超出本地可分配量或不是非负整数。':''});}catch(e){if(scope!==currentApiCacheScope()||id!==sequence)return;output.push({...row,error:e.message});}checked.value++;}for(const result of output){if(result.product_id){const total=output.filter(r=>r.product_id===result.product_id).reduce((n,r)=>n+Number(r.quantity),0);if(total>Number(result.available))result.error='同一基础商品的本批分配总量超出本地可用量。';}}results.value=output;}finally{if(scope===currentApiCacheScope()&&id===sequence)busy.value=false;}}
function reset(){sequence++;shops.value=[];rows.value=[];selection.value=[];results.value=[];bootstrap();}
onMounted(()=>{bootstrap();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{sequence++;window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="wb-stock-batch"><el-alert title="库存核对与批量预览：本次不修改 WB 可售库存，也不改变本地实物库存。" :closable="false"/><div class="stock-filters"><el-select v-model="shop" :disabled="busy" placeholder="选择店铺" @change="load"><el-option v-for="s in shops" :key="s.id" :value="Number(s.id)" :label="s.name"/></el-select><el-select v-model="warehouse" :disabled="busy" placeholder="店铺绑定的卖家仓"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select><el-input v-model="search" placeholder="商品名 / 货号 / 条码" clearable/><el-button :disabled="busy" @click="load">刷新商品</el-button></div><div class="stock-filters"><span>所选规格统一数量</span><el-input-number v-model="quantity" :min="0" :precision="0" :disabled="busy"/><el-button :disabled="busy||!selection.length" @click="apply">填入所选</el-button><el-button type="primary" :disabled="!selection.length||!warehouse" :loading="busy" @click="preview">核对并预览</el-button><span>已选 {{selection.length}} · 已核对 {{checked}}</span></div><el-table :data="filtered" row-key="key" border stripe @selection-change="selection=$event"><el-table-column type="selection" width="46" :selectable="()=>!busy"/><el-table-column label="商品" min-width="330"><template #default="{row}"><div class="stock-product"><WbProductImages :card="row.card"/><div>{{row.title}}<p>{{row.vendor_code}}</p></div></div></template></el-table-column><el-table-column prop="size" label="规格"/><el-table-column prop="barcode" label="条码" min-width="180"/><el-table-column label="目标可售数量" width="180"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0" :precision="0" :disabled="busy"/></template></el-table-column></el-table><el-table v-if="results.length" :data="results" border class="stock-results"><el-table-column prop="vendor_code" label="货号"/><el-table-column label="WB 当前库存"><template #default="{row}">{{row.current??'未返回'}}</template></el-table-column><el-table-column label="本地可分配"><template #default="{row}">{{row.available??'未核对'}}</template></el-table-column><el-table-column prop="quantity" label="目标数量"/><el-table-column label="核对结果"><template #default="{row}">{{row.error||'可预览；尚未提交修改'}}</template></el-table-column></el-table></div></template>
<style scoped>.wb-stock-batch{display:grid;gap:14px}.stock-filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.stock-filters>.el-select{width:220px}.stock-filters>.el-input{width:280px}.stock-product{display:flex;align-items:center;gap:10px;min-height:92px}.stock-product>.el-image{width:64px;height:84px;flex:none}.stock-product p{color:var(--el-text-color-secondary);font-size:12px}.stock-results{margin-top:12px}</style>

<style scoped>.stock-empty-thumb{width:64px;height:84px;flex:none;display:flex;align-items:center;justify-content:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary);border-radius:4px}</style>
